using RyanAssets.GameFeel;
using RyanAssets.UI;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Universes.UniverseData.tower_defense.Client {
    /// <summary>
    /// Tower Defense's screen UI (generated by TD_HudAuthoring): the cash / wave / base status bar (with
    /// the mode), the mode vote before wave 1, the next-wave preview, the fast-forward pill, the boss
    /// health bar, the tower shop (locked towers show their unlock level), the ability pills, the
    /// focused pad or tower card, toasts, the wave banner and the end-of-game result with its star
    /// rating and the player's record. The shared retention HUD (level, challenges, match summary)
    /// is nested beside it. Pure view: <see cref="TD_ClientController"/> feeds it game state.
    /// </summary>
    public sealed class TD_Hud : MonoBehaviour {
        [Header("Status bar")]
        public TMP_Text cashLabel;
        public RectTransform cashPunch;
        public TMP_Text waveTitle, waveStatus;
        [Tooltip("The mode being played (or leading the vote), above the wave title, in the mode's colour.")]
        public TMP_Text modeLabel;
        public Image waveStatusIcon;
        [Tooltip("Bar fills are sized by their right anchor so rounded ends stay round.")]
        public Image waveProgress, baseFill;
        public TMP_Text baseLabel;
        public RectTransform basePunch;
        [Tooltip("The base icon; pulses red while the base is critical (the standing warning; the screen only flashes on a leak).")]
        public Image baseIconImage;
        [Min(0.1f)] public float criticalPulsesPerSecond = 1.4f;
        [Range(0f, 0.5f)] public float criticalPulseScale = 0.16f;
        [Tooltip("How far the critical base icon pulses from red toward white.")]
        [Range(0f, 1f)] public float criticalPulseWhiten = 0.35f;

        [Header("Next wave")]
        public TD_Fader nextWave;
        [Tooltip("Index-aligned with TD_EnemyKind.")]
        public TD_EnemyChip[] enemyChips;
        public TMP_Text readyLabel;
        public Image readyBack;

        [Header("Fast forward")]
        public TD_Fader speedPill;
        public TMP_Text speedLabel;
        public Image speedBack;

        [Header("Boss")]
        public TD_Fader bossPanel;
        [Tooltip("Gap between the boss bar (left of centre) and the fast-forward pill beside it.")]
        public float bossPillGap = 8f;
        public TMP_Text bossLabel;
        [Tooltip("Sized by its right anchor like the other bars.")]
        public Image bossFill;

        [Header("Shop")]
        [Tooltip("The shop dock; hidden while the result card shows.")]
        public CanvasGroup shopGroup;
        public TD_ShopCard[] shopCards;
        [Tooltip("Index-aligned with TD_TowerKind; also used by the info card.")]
        public Sprite[] towerPortraits;

        [Header("Mode vote")]
        public TD_Fader votePanel;
        [Tooltip("Index-aligned with TD_Difficulty.")]
        public TD_ModeCard[] modeCards;
        public TMP_Text voteTitle, voteHint;
        [Tooltip("Under the vote title: what today's modifier does (TD_ModifierStats.blurb).")]
        public TMP_Text voteToday;

        [Header("Abilities")]
        [Tooltip("Index-aligned with TD_Ability.")]
        public TD_AbilityPill[] abilityPills;
        [Tooltip("Pills are opaque in every state so their text reads over bright ground and towers: only the icon dims (to this alpha) while the ability cannot be used.")]
        [Range(0f, 1f)] public float abilityIdleIconAlpha = 0.45f;
        [Tooltip("A usable pill's background leans this far from the dark surface toward the ability's colour.")]
        [Range(0f, 1f)] public float abilityReadyTint = 0.4f;
        [Tooltip("Background alpha of every pill (the theme surface alone is see-through).")]
        [Range(0f, 1f)] public float abilityBackAlpha = 0.96f;

        [Header("New enemies")]
        public TD_EnemyIntro enemyIntro;
        [Tooltip("Index-aligned with TD_EnemyKind (the next-wave chips' pictures).")]
        public Sprite[] enemyPortraits;

        [Header("Popups")]
        [Tooltip("Panels of the top band world popups are kept clear of (TD_ScreenGuard): status bar, pill row, toast, banner.")]
        public RectTransform[] keepClear;

        [Header("Focus")]
        public TD_InfoPanel info;
        public TD_Fader prompt;
        public TMP_Text promptLabel;

        [Header("Messages")]
        public TD_Fader toast;
        public Image toastIcon;
        public TMP_Text toastLabel;
        public TD_Fader banner;
        public Image bannerIcon;
        public TMP_Text bannerTitle, bannerSubtitle;
        public TD_Fader result;
        public Image resultIcon;
        public TMP_Text resultTitle, resultSubtitle, resultRecord, resultCountdown;
        [Tooltip("The win's rating (TD_Rules.Stars of the base left); hidden on a defeat.")]
        public Image[] resultStars;
        public TMP_Text resultMode;
        public Color starOff = new(1f, 1f, 1f, 0.16f);
        [Tooltip("Each result star pops in this many seconds after the one before.")]
        [Min(0f)] public float starRevealInterval = 0.25f;

        [Header("Icons")]
        public Sprite timerIcon, enemiesIcon, coinIcon, baseIcon, readyIcon, waveIcon, trophyIcon, defeatIcon, upgradeIcon;

        [Header("Timing")]
        [Min(0.1f)] public float bannerSeconds = 2.2f;

        // Key labels come from TD_ClientController (SetKeys), which reads the keys.
        string readyKey = "R", fastForwardKey = "G", interactKey = "E";
        readonly string[] abilityKeys = { "F", "V" };

        int shownCash = -1, shownBase = -1, shownBosses = -1, shownChipWave = -1, shownTitleWave = -1, myVote = -1;
        // ShowVote rebuilds its texts only when these change.
        int shownVoteSeconds = -1, shownVoteLocks = -1, shownVoteChoice = -2;
        TD_Modifier shownVoteModifier = (TD_Modifier)byte.MaxValue;
        float toastUntil, bannerUntil, cashKick, baseKick, starsShownAt;
        bool baseCritical, speedBesideBoss, resultShown;
        int resultStarCount;
        TD_ProfileBroadcast profile;
        bool hasProfile;
        readonly bool[] abilityWasReady = new bool[TD_Abilities.Count];
        Color baseIconColor;
        UITheme theme;
        RectTransform speedRect;

        void Awake() {
            theme = UITheme.Active;
            for (int i = 0; i < shopCards.Length; i++)
                shopCards[i].Init(TD_Palette.Tower((TD_TowerKind)i), theme.danger, theme.currency);
            toast.Set(false, true);
            banner.Set(false, true);
            result.Set(false, true);
            nextWave.Set(false, true);
            if (votePanel != null) votePanel.Set(false, true);
            if (enemyIntro != null) enemyIntro.fader.Set(false, true);
            if (modeLabel != null) modeLabel.text = "";
            foreach (var pill in abilityPills ?? System.Array.Empty<TD_AbilityPill>()) pill.group.alpha = 0f;
            speedPill.Set(false, true);
            bossPanel.Set(false, true);
            prompt.Set(false, true);
            info.fader.Set(false, true);
            waveTitle.text = "TOWER DEFENSE";
            waveStatus.text = "Connecting...";
            Bar(waveProgress, 0f);
            cashLabel.text = "$0";
            baseLabel.text = "";
            resultRecord.text = "";
            if (baseIconImage != null) baseIconColor = baseIconImage.color;
            speedRect = speedPill.transform as RectTransform;
        }

        /// <summary>Key names shown in the pills and prompts, as the controller has them bound.</summary>
        public void SetKeys(string ready, string fastForward, string interact) {
            readyKey = ready;
            fastForwardKey = fastForward;
            interactKey = interact;
        }

        /// <summary>Key names of the abilities (index = <see cref="TD_Ability"/>).</summary>
        public void SetAbilityKeys(string airstrike, string emp) {
            abilityKeys[0] = airstrike;
            abilityKeys[1] = emp;
            for (int i = 0; abilityPills != null && i < abilityPills.Length && i < abilityKeys.Length; i++)
                if (abilityPills[i].keyLabel != null) abilityPills[i].keyLabel.text = abilityKeys[i];
        }

        void Update() {
            float dt = Time.unscaledDeltaTime;
            if (toast.Visible && Time.unscaledTime > toastUntil) toast.Set(false);
            if (banner.Visible && Time.unscaledTime > bannerUntil) banner.Set(false);
            cashKick = Kick(cashPunch, cashKick, dt);
            baseKick = Kick(basePunch, baseKick, dt);
            PulseBaseIcon();
            RevealStars();
        }

        /// <summary>The result's stars pop in one by one after the card appears.</summary>
        void RevealStars() {
            if (!resultShown || resultStars == null) return;
            for (int i = 0; i < resultStars.Length; i++) {
                bool lit = i < resultStarCount && Time.unscaledTime >= starsShownAt + (i + 1) * starRevealInterval;
                Color wanted = lit ? TD_Palette.Star : starOff;
                if (resultStars[i].color == wanted) continue;
                resultStars[i].color = wanted;
                if (lit) {
                    Punch.Pop(resultStars[i].rectTransform);
                    GameSfx.Play(SfxCue.Coin, 1f, GameSfx.Semitones(i * 2f));
                }
            }
        }

        /// <summary>While the base is critical its icon throbs red; otherwise it keeps its authored colour.</summary>
        void PulseBaseIcon() {
            if (baseIconImage == null || !baseCritical) return;
            float pulse = 0.5f + 0.5f * Mathf.Sin(Time.unscaledTime * criticalPulsesPerSecond * Mathf.PI * 2f);
            baseIconImage.color = Color.Lerp(theme.danger, Color.white, pulse * criticalPulseWhiten);
            if (baseKick <= 0f && basePunch != null) basePunch.localScale = Vector3.one * (1f + criticalPulseScale * pulse);
        }

        void SetBaseCritical(bool critical) {
            if (critical == baseCritical) return;
            baseCritical = critical;
            if (!critical && baseIconImage != null) {
                baseIconImage.color = baseIconColor;
                if (basePunch != null) basePunch.localScale = Vector3.one;
            }
        }

        static float Kick(RectTransform target, float amount, float dt) {
            if (target == null) return 0f;
            amount = Mathf.MoveTowards(amount, 0f, dt * 2.5f);
            target.localScale = Vector3.one * (1f + 0.18f * amount);
            return amount;
        }

        // ---------------------------------------------------------------- state
        public void ShowState(in TD_StateBroadcast state, bool ready, bool fastVote) {
            // The state arrives on every kill: rebuild a label only when its value changed.
            if (state.cash != shownCash) {
                if (shownCash >= 0) cashKick = 1f;
                shownCash = state.cash;
                cashLabel.text = $"${state.cash:N0}";
            }
            if (state.baseHealth != shownBase) {
                if (shownBase >= 0 && state.baseHealth < shownBase) baseKick = 1f;
                shownBase = state.baseHealth;
                float baseFraction = Mathf.Clamp01(state.baseHealth / (float)TD_Rules.BaseHealth);
                Bar(baseFill, baseFraction);
                baseFill.color = TD_Palette.Health(baseFraction);
                baseLabel.text = $"{Mathf.Max(0, state.baseHealth)}<size=70%><color=#B4BCC8> / {TD_Rules.BaseHealth}</color></size>";
            }
            SetBaseCritical(state.baseHealth > 0 && state.baseHealth <= TD_Rules.BaseCriticalHealth && state.phase is TD_Phase.Build or TD_Phase.Wave);

            int titleWave = state.phase is TD_Phase.Waiting or TD_Phase.Vote ? 0 : state.wave;
            int titleKey = titleWave * 1000 + state.waveCount;
            if (titleKey != shownTitleWave) {
                shownTitleWave = titleKey;
                waveTitle.text = titleWave == 0 ? "TOWER DEFENSE"
                    : state.waveCount <= 0 ? $"WAVE {state.wave}<size=65%><color=#B4BCC8>  endless</color></size>"
                    : $"WAVE {state.wave}<size=65%><color=#B4BCC8> / {state.waveCount}</color></size>";
            }
            if (modeLabel != null) {
                bool showMode = state.phase != TD_Phase.Waiting;
                string day = TD_Daily.Get(state.modifier).name;
                modeLabel.text = !showMode ? "" : TD_Modes.Get(state.mode).name.ToUpperInvariant() + (day.Length > 0 ? $"  ·  {day.ToUpperInvariant()}" : "");
                modeLabel.color = TD_Palette.Mode(state.mode);
            }
            if (info != null) info.modifier = state.modifier;
            int total = Mathf.Max(1, TD_Rules.EnemyCount(state.wave));
            switch (state.phase) {
                case TD_Phase.Waiting:
                    Status("Waiting for players", timerIcon, 0f);
                    break;
                case TD_Phase.Vote:
                    Status($"Mode vote  ·  {state.secondsLeft}s", timerIcon, 1f);
                    break;
                case TD_Phase.Build:
                    Status($"Build phase  ·  {state.secondsLeft}s", timerIcon, 1f);
                    break;
                case TD_Phase.Wave:
                    string fast = state.speed > 1f ? $"  ·  {state.speed:0.#}x" : "";
                    Status($"{state.enemiesLeft} {(state.enemiesLeft == 1 ? "enemy" : "enemies")} left{fast}", enemiesIcon, state.enemiesLeft / (float)total);
                    break;
                default:
                    Status(state.phase == TD_Phase.Victory ? "Victory!" : "Base destroyed", state.phase == TD_Phase.Victory ? trophyIcon : defeatIcon, 0f);
                    break;
            }

            ShowNextWave(state, ready);
            ShowSpeed(state, fastVote);
            ShowResult(state);
            ShowVote(state);
            if (state.phase != TD_Phase.Wave) ShowBoss(0, 0f);
        }

        void Status(string text, Sprite icon, float progress) {
            waveStatus.text = text;
            waveStatusIcon.sprite = icon;
            Bar(waveProgress, progress);
        }

        static void Bar(Image fill, float fraction) {
            fill.rectTransform.anchorMax = new Vector2(Mathf.Clamp01(fraction), 1f);
            fill.enabled = fraction > 0.001f;
        }

        void ShowNextWave(in TD_StateBroadcast state, bool ready) {
            bool show = state.phase == TD_Phase.Build;
            nextWave.Set(show);
            if (!show) return;
            if (state.wave != shownChipWave) {
                shownChipWave = state.wave;
                int[] counts = TD_Rules.WaveCounts(state.wave); // the enemy mix is the same on every mode
                for (int i = 0; i < enemyChips.Length && i < counts.Length; i++) {
                    var chip = enemyChips[i];
                    chip.root.SetActive(counts[i] > 0);
                    chip.count.text = $"×{counts[i]}";
                    // The wave that brings a kind for the first time says what it is on its chip.
                    bool isNew = TD_Rules.IsNew((TD_EnemyKind)i, state.wave);
                    if (chip.trait != null) {
                        chip.trait.gameObject.SetActive(isNew);
                        if (isNew) chip.trait.text = $"NEW  <color=#{ColorUtility.ToHtmlStringRGB(TD_Palette.Enemy((TD_EnemyKind)i))}>{TD_Rules.Enemy((TD_EnemyKind)i).trait}</color>";
                    }
                }
            }
            int players = Mathf.Max(1, (int)state.activePlayers);
            int bonus = TD_Rules.EarlyStartBonus(state.wave, state.secondsLeft);
            string reward = bonus > 0 ? $"  <color=#{ColorUtility.ToHtmlStringRGB(theme.currency)}>+${bonus}</color>" : "";
            readyLabel.text = ready
                ? $"Ready{reward}  <color=#B4BCC8>{state.readyPlayers}/{players}</color>"
                : $"<color=#B4BCC8>[{readyKey}]</color>  Start now{reward}  <color=#B4BCC8>{state.readyPlayers}/{players}</color>";
            readyBack.color = ready ? theme.success : theme.surfaceHover;
        }

        void ShowSpeed(in TD_StateBroadcast state, bool fastVote) {
            bool show = state.phase == TD_Phase.Wave && state.fastForwardAllowed;
            speedPill.Set(show);
            if (!show) return;
            bool fast = state.speed > 1f;
            int players = Mathf.Max(1, (int)state.activePlayers);
            speedLabel.text = $"<color=#B4BCC8>[{fastForwardKey}]</color>  {(fast ? $"Fast forward {TD_Rules.FastSpeed:0.#}x" : "Fast forward")}  <color=#B4BCC8>{state.fastPlayers}/{players}</color>";
            speedBack.color = fast ? theme.accent : fastVote ? theme.success : theme.surfaceHover;
        }

        /// <summary>
        /// The boss bar, in the pill row under the status bar: health of the lead boss and how many are
        /// on the road. While it shows, the fast-forward pill steps aside to its right.
        /// </summary>
        public void ShowBoss(int count, float health) {
            if (count != shownBosses) {
                shownBosses = count;
                bossPanel.Set(count > 0);
                if (count > 0) {
                    string name = TD_Rules.Enemy(TD_EnemyKind.Boss).name.ToUpperInvariant();
                    bossLabel.text = count > 1 ? $"{name}  <color=#B4BCC8>×{count}</color>" : name;
                }
                PlaceSpeedPill(count > 0);
            }
            if (count > 0) Bar(bossFill, health);
        }

        void PlaceSpeedPill(bool besideBoss) {
            if (speedRect == null || besideBoss == speedBesideBoss) return;
            speedBesideBoss = besideBoss;
            speedRect.pivot = new Vector2(besideBoss ? 0f : 0.5f, 1f);
            speedRect.anchoredPosition = new Vector2(besideBoss ? bossPillGap : 0f, speedRect.anchoredPosition.y);
        }

        /// <summary>The player's saved record: the vote cards' bests and the result card's record line (with "New best!" when this game set it).</summary>
        public void ShowRecord(in TD_ProfileBroadcast record) {
            profile = record;
            hasProfile = true;
            string gold = ColorUtility.ToHtmlStringRGB(theme.currency);
            string best = record.newBestWave || record.newBestEndless ? $"<color=#{gold}><b>New best!</b></color>  " : "";
            string endless = record.bestEndlessWave > 0 ? $"  ·  Endless best: wave {record.bestEndlessWave}" : "";
            resultRecord.text = record.bestWave > 0
                ? $"{best}Personal best: wave {record.bestWave}{endless}  ·  {record.gamesWon} {(record.gamesWon == 1 ? "win" : "wins")}  ·  {record.totalKills:N0} kills"
                : "";
        }

        int BestStars(TD_Difficulty mode) => hasProfile && profile.bestStars != null && (int)mode < profile.bestStars.Length ? profile.bestStars[(int)mode] : 0;

        void ShowResult(in TD_StateBroadcast state) {
            bool over = state.phase is TD_Phase.Victory or TD_Phase.Defeat;
            result.Set(over);
            if (shopGroup != null) shopGroup.alpha = over ? 0f : 1f;
            if (!over) {
                resultShown = false;
                return;
            }
            bool won = state.phase == TD_Phase.Victory;
            var mode = TD_Modes.Get(state.mode);
            int stars = won ? TD_Rules.Stars(state.baseHealth) : 0;
            if (!resultShown) {
                resultShown = true;
                starsShownAt = Time.unscaledTime;
                resultStarCount = stars;
                if (resultStars != null) foreach (var star in resultStars) star.color = starOff;
            }
            if (resultStars != null) foreach (var star in resultStars) star.gameObject.SetActive(won);
            resultIcon.sprite = won ? trophyIcon : defeatIcon;
            resultIcon.color = won ? theme.currency : theme.danger;
            resultTitle.text = won ? "VICTORY" : "BASE DESTROYED";
            if (resultMode != null) {
                resultMode.text = mode.name.ToUpperInvariant();
                resultMode.color = TD_Palette.Mode(state.mode);
            }
            int best = BestStars(state.mode);
            resultSubtitle.text = won
                ? $"The base held all {state.waveCount} waves with {state.baseHealth} health left." + (best > stars ? $"  Your best here: {best} / {TD_Rules.MaxStars}." : "")
                : mode.Endless
                    ? $"The defence held {Mathf.Max(0, state.wave - 1)} endless waves."
                    : $"The defence fell on wave {state.wave} of {state.waveCount}.";
            resultCountdown.text = $"New game in {state.secondsLeft}";
        }

        // ---------------------------------------------------------------- mode vote
        void ShowVote(in TD_StateBroadcast state) {
            if (votePanel == null) return;
            bool show = state.phase == TD_Phase.Vote;
            votePanel.Set(show);
            if (!show) return;
            int lockMask = 0;
            for (int i = 0; i < modeCards.Length && i < TD_Modes.Count; i++) {
                var mode = (TD_Difficulty)i;
                bool unlocked = ModeOpen(mode);
                if (!unlocked) lockMask |= 1 << i;
                int votes = state.modeVotes != null && i < state.modeVotes.Length ? state.modeVotes[i] : 0;
                modeCards[i].Set(mode, unlocked, BestStars(mode), hasProfile ? profile.bestEndlessWave : 0, votes, i == myVote, mode == state.mode);
            }
            // The texts change a few times a vote; rebuild them only then (this runs on every state update).
            if (state.secondsLeft != shownVoteSeconds || state.modifier != shownVoteModifier) {
                shownVoteSeconds = state.secondsLeft;
                shownVoteModifier = state.modifier;
                var day = TD_Daily.Get(state.modifier);
                string today = day.name.Length > 0 ? $"  <color=#{ColorUtility.ToHtmlStringRGB(theme.warning)}>TODAY: {day.name.ToUpperInvariant()}</color>" : "";
                voteTitle.text = $"CHOOSE A MODE{today}  <color=#B4BCC8>{state.secondsLeft}s</color>";
                if (voteToday != null) voteToday.text = day.blurb;
            }
            if (lockMask != shownVoteLocks || myVote != shownVoteChoice) {
                shownVoteLocks = lockMask;
                shownVoteChoice = myVote;
                voteHint.text = myVote >= 0
                    ? $"You voted {TD_Modes.Get((TD_Difficulty)myVote).name}. Most votes wins; a tie goes to the easier mode."
                    : lockMask != 0 ? $"Press 1-3 to vote.  {LockedHints(lockMask)}." : "Press 1-3 to vote. Most votes wins.";
            }
        }

        /// <summary>"Hard: win Normal once  ·  Endless: ..." for the locked modes in <paramref name="lockMask"/>.</summary>
        static string LockedHints(int lockMask) {
            var text = new System.Text.StringBuilder();
            for (int i = 0; i < TD_Modes.Count; i++) {
                if ((lockMask & (1 << i)) == 0) continue;
                var stats = TD_Modes.Get((TD_Difficulty)i);
                if (text.Length > 0) text.Append("  ·  ");
                text.Append(stats.name).Append(": ").Append(LowerFirst(stats.lockedHint));
            }
            return text.ToString();
        }

        /// <summary>Whether the local player may vote for <paramref name="mode"/> (from their profile; Normal always).</summary>
        public bool ModeOpen(TD_Difficulty mode) => TD_Modes.Open(hasProfile ? profile.modeUnlocked : null, mode);

        static string LowerFirst(string text) => string.IsNullOrEmpty(text) ? text : char.ToLowerInvariant(text[0]) + text.Substring(1);

        /// <summary>The local player's vote (-1 = none), outlined on its card.</summary>
        public void SetMyVote(int mode) => myVote = mode;

        // ---------------------------------------------------------------- abilities
        /// <summary>
        /// The ability pills: hidden until the first ability unlocks; a locked one says its level, a
        /// recharging one its waves left, and a ready one lights up (and pops once as it becomes ready).
        /// </summary>
        public void ShowAbilities(in TD_AbilityStateBroadcast abilities, TD_Phase phase, int level) {
            if (abilityPills == null) return;
            bool any = false;
            for (int i = 0; i < TD_Abilities.Count && abilities.unlocked != null && i < abilities.unlocked.Length; i++) any |= abilities.unlocked[i];
            bool playing = phase is TD_Phase.Build or TD_Phase.Wave;
            for (int i = 0; i < abilityPills.Length && i < TD_Abilities.Count; i++) {
                var pill = abilityPills[i];
                var ability = (TD_Ability)i;
                var stats = TD_Abilities.Get(ability);
                bool unlocked = abilities.unlocked != null && i < abilities.unlocked.Length && abilities.unlocked[i];
                int left = abilities.wavesLeft != null && i < abilities.wavesLeft.Length ? abilities.wavesLeft[i] : 0;
                bool ready = unlocked && left == 0;
                bool usable = ready && phase == TD_Phase.Wave;
                // Shown once any ability is owned (the locked one then says when it comes); hidden at game over.
                // Never see-through while shown: "2 waves" or "Level 11" has to read over grass and towers.
                pill.group.alpha = !any || !playing ? 0f : 1f;
                pill.nameLabel.text = stats.name;
                pill.stateLabel.text = !unlocked ? $"Level {TD_Retention.LevelOf(stats.unlockId)}"
                    : left > 0 ? (left == 1 ? "Next wave" : $"{left} waves")
                    : phase == TD_Phase.Wave ? "Ready!" : "Ready next wave";
                Color accent = TD_Palette.Ability(ability);
                Color icon = unlocked ? accent : theme.textMuted;
                if (!usable) icon.a *= abilityIdleIconAlpha;
                pill.icon.color = icon;
                // Usable: the dark surface tinted with the ability's colour (a see-through accent washed the
                // white label out over bright ground); otherwise the plain surface, made opaque.
                Color back = usable ? Color.Lerp(theme.surface, accent, abilityReadyTint) : theme.surface;
                back.a = abilityBackAlpha;
                pill.back.color = back;
                if (usable && !abilityWasReady[i] && pill.punch != null) Punch.Pop(pill.punch);
                abilityWasReady[i] = usable;
            }
        }

        // ---------------------------------------------------------------- shop + focus
        /// <param name="level">The player's Tower Defense level: towers above it show their unlock level.</param>
        public void ShowShop(int selected, int cash, bool hasState, int level) {
            for (int i = 0; i < shopCards.Length && i < TD_Rules.Towers.Length; i++) {
                var kind = (TD_TowerKind)i;
                shopCards[i].Set(i == selected, !hasState || cash >= TD_Rules.Towers[i].cost, TD_Retention.CanBuild(level, kind) ? 0 : TD_Retention.LevelOf(TD_Rules.Tower(kind).unlockId));
            }
        }

        public Sprite Portrait(TD_TowerKind kind) => towerPortraits != null && (int)kind < towerPortraits.Length ? towerPortraits[(int)kind] : null;

        public Sprite Portrait(TD_EnemyKind kind) => enemyPortraits != null && (int)kind < enemyPortraits.Length ? enemyPortraits[(int)kind] : null;

        // ---------------------------------------------------------------- new enemies
        /// <summary>The new-enemy card for <paramref name="wave"/> (hidden when it brings no new kind).</summary>
        public void ShowIntro(int wave) {
            if (enemyIntro != null) enemyIntro.Show(wave, Portrait);
        }

        public void HideIntro() {
            if (enemyIntro != null) enemyIntro.Hide();
        }

        /// <summary>A new game: its new enemies are introduced again.</summary>
        public void ResetIntro() {
            if (enemyIntro != null) enemyIntro.ResetWave();
        }

        /// <param name="unlockLevel">The level that unlocks <paramref name="selected"/>, or 0 when owned.</param>
        public void ShowFocusPad(TD_TowerKind selected, int cash, int unlockLevel) {
            info.ShowBuild(selected, Portrait(selected), cash, unlockLevel);
            var t = TD_Rules.Tower(selected);
            string action = unlockLevel > 0 ? $"<color=#B4BCC8>The {t.name} unlocks at level {unlockLevel}</color>"
                : cash >= t.cost ? $"<b>{interactKey}</b>  Build {t.name}"
                : $"<color=#{ColorUtility.ToHtmlStringRGB(theme.danger)}>Need ${t.cost - cash} more for a {t.name}</color>";
            Prompt($"{action}     <color=#B4BCC8><b>1-{TD_Rules.Towers.Length}</b>  Change tower</color>");
        }

        /// <param name="canSell">False for another player's tower: no sell offer, the card says who can sell it.</param>
        /// <param name="upgradeDiscount">The viewer's upgrade discount (Field Engineers): they pay the upgrade.</param>
        public void ShowFocusTower(in TD_TowerSnap tower, int cash, string sellKey, bool canSell, float upgradeDiscount) {
            int cost = TD_Rules.UpgradeCost(tower.kind, tower.level, upgradeDiscount);
            info.ShowTower(tower, Portrait(tower.kind), cash, sellKey, canSell, cost);
            string sell = canSell ? $"<b>{sellKey}</b>  Sell +${TD_InfoPanel.RefundOf(tower)}" : "";
            if (tower.level >= TD_Rules.MaxLevel) {
                Prompt(sell);
                return;
            }
            string upgrade = cash >= cost
                ? $"<b>{interactKey}</b>  Upgrade {TD_Rules.Tower(tower.kind).name}"
                : $"<color=#{ColorUtility.ToHtmlStringRGB(theme.danger)}>Need ${cost - cash} more for Lv {tower.level + 1}</color>";
            Prompt(canSell ? $"{upgrade}     <color=#B4BCC8>{sell}</color>" : upgrade);
        }

        public void ClearFocus() {
            info.Hide();
            prompt.Set(false);
        }

        void Prompt(string text) {
            prompt.Set(text.Length > 0);
            if (text.Length > 0) promptLabel.text = text;
        }

        // ---------------------------------------------------------------- messages
        public enum ToastKind { Info, Good, Bad, Money }

        public void Toast(string message, ToastKind kind, float seconds) {
            toastLabel.text = message;
            (Sprite icon, Color color) = kind switch {
                ToastKind.Good => (readyIcon, theme.success),
                ToastKind.Bad => (baseIcon, theme.danger),
                ToastKind.Money => (coinIcon, theme.currency),
                _ => (upgradeIcon, theme.accent),
            };
            toastIcon.sprite = icon;
            toastIcon.color = color;
            toast.Set(true);
            // Size the pill to the new message now, not at the next canvas rebuild, so a popup spawned this
            // frame is kept clear of the toast as it will be drawn.
            LayoutRebuilder.ForceRebuildLayoutImmediate((RectTransform)toast.transform);
            toastUntil = Time.unscaledTime + seconds;
        }

        public void Banner(string title, string subtitle, bool boss = false) {
            bannerIcon.color = boss ? theme.danger : theme.warning;
            bannerTitle.text = title;
            bannerSubtitle.text = subtitle;
            banner.Set(true);
            bannerUntil = Time.unscaledTime + bannerSeconds;
        }
    }
}
